            output.WriteByte(sectionId);
            WriteULEB128(output, checked((uint)module.Length));
            output.Write(module, 0, module.Length);
            replaced = true;
        }
        else
        {
            output.Write(component, sectionStart, sectionEnd - sectionStart);
        }
        position = sectionEnd;
    }

    if (!replaced)
